use std::collections::HashMap;

fn two_sum(nums: &Vec<i32>, target: i32) -> Vec<usize> {
    let mut seen: HashMap<i32, usize> = HashMap::new();
    for (i, &num) in nums.iter().enumerate() {
        let complement = target - num;
        if let Some(&j) = seen.get(&complement) {
            // j < i by construction, so they are already in increasing order
            return vec![j, i];
        }
        seen.insert(num, i);
    }
    // According to the problem statement, there is always exactly one solution
    unreachable!("Exactly one solution is guaranteed");
}

